  "carya-illinoinensis": {
    "speciesId": "carya-illinoinensis",
    "name": "Pecan",
    "product": "nut in shell",
    "windows": [
      {
        "region": "South Africa (general — Southern Hemisphere phenology; main areas Vaalharts/Northern Cape, Lower Orange River)",
        "months": [
          3,
          4,
          5,
          6
        ],
        "source": {
          "quote": "Shell hardening and nut-fill is complete around end of February, taking approximately three weeks. At this stage shuck-split will take place which indicates the start of the harvesting period, ending in middle June. Trees then enter dormancy after natural leaf drop end of July.",
          "url": "https://www.sappa.za.org/download/16968/?tmstv=1790592292",
          "doc": "Lötze, E., 'Literature Review: Factors influencing pollination of pecans for commercial production', published by SAPPA (South African Pecan Nut Producers' Association)",
          "page": 3
        }
      }
    ],
    "yearsToFirstCrop": {
      "value": [
        5,
        5
      ],
      "source": {
        "quote": "Light cropping starts at about 5 years, with full production in year 12-13.",
        "url": "https://www.kzndard.gov.za/images/Documents/Horticulture/Veg_prod/Fruit%20and%20%20Nut%20Production%20in%20KZN.pdf",
        "doc": "KZN DARD, Fruit and Nut Production in KZN, Pecan bearing age; printed p.22",
        "page": 26
      },
      "note": "Light cropping at about year 5 in the KZN guide, for irrigated areas with hot summers, cold winters and low growing-season humidity. It identifies dry Zululand/Lowveld river valleys as suitable regional areas. Propagation, cultivar and nursery age are not specified; this is a qualified general reference, not an expected farm quantity."
    },
    "yearsToFullBearing": {
      "value": [
        12,
        13
      ],
      "source": {
        "quote": "Light cropping starts at about 5 years, with full production in year 12-13.",
        "url": "https://www.kzndard.gov.za/images/Documents/Horticulture/Veg_prod/Fruit%20and%20%20Nut%20Production%20in%20KZN.pdf",
        "doc": "KZN DARD, Fruit and Nut Production in KZN, Pecan bearing age; printed p.22",
        "page": 26
      },
      "note": "Full production around years 12–13 in the general KZN guide. Cultivar, propagation, density and management affect actual output; mature ages do not automatically create an annual kg/tree curve."
    },
    "yieldKgPerTree": null,
    "chillUnits": null,
    "pollination": {
      "value": "needs-cross-pollinator",
      "source": {
        "quote": "In pecans [Carya illinoinensis (Wangenh. K. Koch)], male (staminate) and female (pistillate) flowers occur on the same tree (monoecious) and exhibits heterodichogamy ... Therefore, trees were divided into two groups: “Protandrous” (Type I) which is when pollen from the male flowers is shed before the female flowers are receptive, and “Protogynous” (Type II), where female flowers are receptive to pollen before pollen is shed from the male flowers ... Compatible cultivars need to be in close proximity to each other for successful cross-pollination ... It is possible for fruit to set through self-pollination in the case of incomplete dichogamy, but this often results in smaller and lighter nuts ... Under self-pollination, pecan yield is 35 – 75% lower with nut quality severely reduced (Polles et al., 1980). Complete dichogamy will result in a self-sterile cultivar, as there is no overlap between pollen shed and pistil receptivity.",
        "url": "https://www.sappa.za.org/download/16968/?tmstv=1790592292",
        "doc": "Lötze, E., 'Literature Review: Factors influencing pollination of pecans for commercial production', published by SAPPA",
        "page": 2
      },
      "note": "Pecan is wind-pollinated and monoecious (male and female flowers on the same tree) but exhibits heterodichogamy — male and female flowers on a given tree mature at different times (Type I protandrous vs Type II protogynous) — so a single tree/cultivar alone generally cannot pollinate itself well or at all (many named cultivars are effectively self-sterile), and commercial orchards in South Africa are planted with complementary Type I x Type II cultivar combinations. Self-pollination is possible in some cultivars with incomplete dichogamy but yields 35-75% less with poorer nut quality — hence 'needs-cross-pollinator' rather than 'partly-self-fertile' or 'self-fertile'."
    },
    "supplementaryReferences": [
      {
        "title": "Pecan guide output — dry nut-in-shell hectare basis",
        "source": {
          "quote": "Dry-in-Shell",
          "url": "https://www.kzndard.gov.za/images/Documents/Horticulture/Veg_prod/Fruit%20and%20%20Nut%20Production%20in%20KZN.pdf",
          "doc": "KZN DARD, Fruit and Nut Production in KZN, Pecan yield; printed p.22",
          "page": 26
        },
        "note": "The guide gives conservative 750, average 800–1,200 and good 1,500+ kg/ha Dry-in-Shell. It separately lists alternative tree spacings and later thinning, so one density is not assumed. These are unaged hectare benchmarks; shell weight is not edible kernel weight and no generic kg/tree curve is derived."
      }
    ]
  },
